                    <p>
                      Scheduled:{' '}
                      {latestDraft.scheduledAt
                        ? new Date(latestDraft.scheduledAt).toLocaleString()
                        : 'Unset'}
                    </p>
                    <p>Notes: {latestDraft.notes || 'None'}</p>
