  taxAmount: '0.00',
  subtotalAmount: '25.00',
  taxableAmount: '25.00',
  totalAmount: '25.00',
  notes: null,
  ...stamps,
}
const orderDates = {
  orderedAt: stamps.createdAt,
  expectedAt: '2026-10-11T00:00:00Z',
  confirmedAt: null,
  completedAt: null,
  cancelledAt: null,
  externalReference: null,
  notes: null,
  ...stamps,
}
const salesFixture: SalesOrderRecord = {
  id: 1,
  revision: 1,
  orderNumber: 'SO-TEST',
