  notes: null,
  ...stamps,
  items: [
    {
      id: id * 10,
      incomingDeliveryId: id,
      purchaseOrderItemId: 20,
      receivedQuantity: '0.20',
      acceptedQuantity: '0.20',
      ...stamps,
    },
