    outgoingFixture(6, 'SCHEDULED'),
    outgoingFixture(7, 'DELIVERED'),
    outgoingFixture(8, 'CANCELLED'),
  ]
  failSchedule = false
  failConfirmation = false
  failCreation = false
  failCancellation = false
  requestGate = undefined
  failReceipt = false
  failIncomingQuery = false
  requests = []
  vi.mocked(exportPurchaseReceiptPdf).mockClear()
  apiClient.defaults.adapter = async (config) => {
    const url = config.url || ''
    const method = config.method || 'get'
    const body = typeof config.data === 'string' ? JSON.parse(config.data) : config.data || {}
    requests.push({ method, url, body })
    if (method !== 'get' && requestGate?.url === url) await requestGate.wait
    if (method === 'get' && url === '/incoming-deliveries' && failIncomingQuery) {
      failIncomingQuery = false
      throw { isAxiosError: true, code: 'ERR_NETWORK', message: 'Connection failed' }
    }
    let data: unknown = []
    if (method === 'get') {
      const collections: Record<string, unknown> = {
        '/sales-orders': sales,
        '/purchase-orders': purchases,
        '/incoming-deliveries': incoming,
        '/outgoing-deliveries': outgoing,
        '/inventory-items': [
          {
            id: 1,
            name: 'Test Mango',
            unit: 'kg',
            variety: 'Carabao',
            description: null,
            unitPrice: 100,
            isActive: true,
            ...stamps,
