            isActive: true,
            ...stamps,
          },
        ],
        '/stock-items': [
          {
            id: 1,
            warehouseId: 1,
            inventoryItemId: 1,
            quantity: '20.00',
            reservedQuantity: '1.25',
            ...stamps,
          },
        ],
        '/clients': [
          { id: 1, name: 'Test Customer', address: 'Test Address', isActive: true, ...stamps },
        ],
        '/suppliers': [
          { id: 2, code: 'SUP-TEST', name: 'Test Supplier', isActive: true, ...stamps },
        ],
      }
      data =
        collections[url] ??
        sales.find((item) => url === `/sales-orders/${item.id}`) ??
        purchases.find((item) => url === `/purchase-orders/${item.id}`) ??
        (url === '/outgoing-deliveries/planning-options'
