      outgoingPlanningErrors(
        currentOrder,
        [{ ...option(), maximumPlannableQuantity: '0' }],
        { 10: '1' },
        { 10: '2' },
      )['quantity-10'],
    ).toContain('Maximum plannable quantity is 0.00')
  })
})

