                id: 1,
                payload: {
                  items: [
                    {
                      outgoingDeliveryItemId: 1,
                      deliveredQuantity: '1.00',
                      returnedSellableQuantity: '0.00',
                      returnedDamagedQuantity: '0.00',
                      missingQuantity: '0.00',
