import { useState, type FormEvent } from 'react'
import { parseStockCents } from '@/features/logistics/stock-display'
import { Hash, Gauge, Layers, RotateCcw } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { SearchableDropdown } from '@/components/ui/SearchableDropdown'
import { Spinner } from '@/components/ui/spinner'
import { Alert, AlertDescription } from '@/components/ui/alert'
import {
  useDeliveryVehicles,
  useCreateVehicle,
  useUpdateVehicleDetails,
  useReactivateVehicle,
  fetchVehicleByPlateNumberApi,
} from '@/features/logistics/delivery-vehicles.hooks'
import {
  OPERATIONAL_STATUSES,
  type DeliveryVehicle,
  type VehicleStatus,
} from '@/features/logistics/delivery-vehicles.types'
import { getErrorMessage } from '@/lib/api-client'

type VehicleModalProps = {
  vehicle: DeliveryVehicle | null
  open: boolean
  onClose: () => void
}

const VEHICLE_TYPES = [
  'Heavy Truck (6-Wheeler)',
  'Light Truck (4-Wheeler)',
  'Delivery Van',
  'Cargo Multicab',
  'Cargo Motorcycle',
]

function VehicleFormContent({
  vehicle,
  onClose,
}: {
  vehicle: DeliveryVehicle | null
  onClose: () => void
}) {
  const isEditing = !!vehicle
  const { data: allVehicles = [] } = useDeliveryVehicles()
  const createMutation = useCreateVehicle()
  const updateMutation = useUpdateVehicleDetails()
  const reactivateMutation = useReactivateVehicle()

  const [plateNumber, setPlateNumber] = useState(vehicle?.plateNumber || '')
  const [vehicleType, setVehicleType] = useState(vehicle?.vehicleType || VEHICLE_TYPES[0])
  const [model, setModel] = useState(vehicle?.model || '')
  const [capacity, setCapacity] = useState(vehicle?.capacity ? String(vehicle.capacity) : '')
  const [status, setStatus] = useState<VehicleStatus>(vehicle?.status || 'AVAILABLE')
  const [errorMsg, setErrorMsg] = useState('')
  const [deactivatedVehicleMatch, setDeactivatedVehicleMatch] = useState<DeliveryVehicle | null>(
    null,
  )

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault()
    setErrorMsg('')
    setDeactivatedVehicleMatch(null)

    const cleanPlate = plateNumber.trim().toUpperCase()
    if (!cleanPlate) {
      setErrorMsg('Vehicle plate number is required.')
      return
    }

    if (!isEditing) {
      let backendMatch: DeliveryVehicle | null
      try {
        backendMatch = await fetchVehicleByPlateNumberApi(cleanPlate)
      } catch (err) {
        setErrorMsg(getErrorMessage(err))
        return
      }

      if (
        backendMatch &&
        typeof backendMatch === 'object' &&
        backendMatch.id &&
        backendMatch.isActive === false
      ) {
        setDeactivatedVehicleMatch(backendMatch)
        setErrorMsg(
          `Vehicle with plate number "${cleanPlate}" is currently deactivated. You can reactivate it directly.`,
        )
        return
      }

      // Check if active duplicate exists
      const isDuplicatePlate = allVehicles.some(
        (v) => v.plateNumber.toUpperCase().trim() === cleanPlate && v.isActive !== false,
      )
      if (
        isDuplicatePlate ||
        (backendMatch &&
          typeof backendMatch === 'object' &&
          backendMatch.id &&
          backendMatch.isActive !== false)
      ) {
        setErrorMsg(`A vehicle with plate number "${cleanPlate}" is already active in Vehicles.`)
        return
      }
    }

    if (!vehicleType.trim()) {
      setErrorMsg('Vehicle type is required.')
      return
    }

    if (vehicleType.trim().length > 100) {
      setErrorMsg('Vehicle type must be 100 characters or fewer.')
      return
    }

    const parsedCap = capacity.trim() ? parseStockCents(capacity) : null
    if (capacity.trim() && (parsedCap === null || parsedCap > 999_999_999_999n)) {
      setErrorMsg('Enter a non-negative capacity up to 9,999,999,999.99 with at most two decimal places.')
      return
    }

    try {
      if (isEditing && vehicle) {
        await updateMutation.mutateAsync({
          id: vehicle.id,
          payload: {
            plateNumber: plateNumber.trim().toUpperCase(),
            vehicleType: vehicleType.trim(),
            model: model.trim() || null,
            capacity: capacity.trim() || null,
          },
        })
      } else {
        await createMutation.mutateAsync({
          plateNumber: plateNumber.trim().toUpperCase(),
          vehicleType: vehicleType.trim(),
          model: model.trim() || null,
          capacity: capacity.trim() || null,
          status,
          isActive: true,
        })
      }
      onClose()
    } catch (err) {
      setErrorMsg(getErrorMessage(err))
    }
  }

  const handleRestoreFoundVehicle = async () => {
    if (deactivatedVehicleMatch) {
      await reactivateMutation.mutateAsync(deactivatedVehicleMatch.id)
      onClose()
    }
  }

  const isPending =
    createMutation.isPending || updateMutation.isPending || reactivateMutation.isPending

  return (
    <>
      <DialogHeader>
        <DialogTitle>{isEditing ? 'Edit Vehicle' : 'Add Vehicle'}</DialogTitle>
        <DialogDescription>
          {isEditing
            ? 'Update vehicle specifications, payload capacity, and route.'
            : 'Add an ERJV-controlled vehicle for collections and deliveries.'}
        </DialogDescription>
      </DialogHeader>

      {errorMsg && !deactivatedVehicleMatch && (
        <Alert
          variant="destructive"
          className="animate-in fade-in-0 slide-in-from-top-1 duration-200"
        >
          <AlertDescription>{errorMsg}</AlertDescription>
        </Alert>
      )}

      {deactivatedVehicleMatch && (
        <div className="p-3.5 rounded-lg bg-status-warning border border-status-warning-foreground/30 text-status-warning-foreground flex items-start gap-3">
          <RotateCcw className="mt-0.5 size-4 shrink-0 text-status-warning-foreground" />
          <div className="flex-1 text-xs">
            <p className="font-medium text-foreground">Deactivated Vehicle Found</p>
            <p className="text-muted-foreground mt-0.5 leading-relaxed">
              An archived vehicle record with plate{' '}
              <strong className="tabular-nums text-foreground">
                {deactivatedVehicleMatch.plateNumber}
              </strong>{' '}
              ({deactivatedVehicleMatch.vehicleType}) already exists. Click{' '}
              <strong>"Reactivate Vehicle"</strong> below to restore it.
            </p>
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-3.5 py-1">
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="v-plate" className="text-[13px] font-medium">
              Plate Number <span className="text-primary">*</span>
            </Label>
            <div className="relative">
              <Hash className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
              <Input
                id="v-plate"
                placeholder="e.g. ABC-1234"
                value={plateNumber}
                onChange={(e) => {
                  setPlateNumber(e.target.value)
                  if (deactivatedVehicleMatch) setDeactivatedVehicleMatch(null)
                  if (errorMsg) setErrorMsg('')
                }}
                className="pl-9 uppercase"
                required
              />
            </div>
          </div>

          <div className="flex flex-col gap-1.5">
            <Label htmlFor="v-type" className="text-[13px] font-medium">
              Vehicle Type <span className="text-primary">*</span>
            </Label>
            <SearchableDropdown
              id="v-type"
              options={VEHICLE_TYPES}
              value={vehicleType}
              onValueChange={setVehicleType}
              onCreateValue={setVehicleType}
              maxCustomLength={100}
              getOptionValue={(type) => type}
              getOptionLabel={(type) => type}
              placeholder="Select type..."
              searchPlaceholder="Search or enter vehicle type"
              emptyMessage="No matching vehicle types"
              ariaLabel="Vehicle Type"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="v-model" className="text-[13px] font-medium">
              Model / Make
            </Label>
            <div className="relative">
              <Layers className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
              <Input
                id="v-model"
                placeholder="e.g. Isuzu NPR 75, Toyota HiAce"
                value={model}
                onChange={(e) => setModel(e.target.value)}
                className="pl-9 transition-all duration-200"
              />
            </div>
          </div>

          <div className="flex flex-col gap-1.5">
            <Label htmlFor="v-capacity" className="text-[13px] font-medium">
              Payload Capacity (kg)
            </Label>
            <div className="relative">
              <Gauge className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
              <Input
                id="v-capacity"
                type="number"
                step="0.01"
                min="0"
                placeholder="e.g. 2500"
                value={capacity}
                onChange={(e) => setCapacity(e.target.value)}
                className="pl-9 transition-all duration-200"
              />
            </div>
          </div>
        </div>

        {!isEditing && (
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="v-status" className="text-[13px] font-medium">
              Vehicle Condition
            </Label>
            <Select value={status} onValueChange={(val) => setStatus(val as VehicleStatus)}>
              <SelectTrigger id="v-status">
                <SelectValue placeholder="Select initial status..." />
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  {OPERATIONAL_STATUSES.map((st) => {
                    const label =
                      st === 'AVAILABLE'
                        ? 'Operational'
                        : st === 'MAINTENANCE'
                          ? 'Under Maintenance'
                          : 'Out of Service'

                    return (
                      <SelectItem key={st} value={st}>
                        {label}
                      </SelectItem>
                    )
                  })}
                </SelectGroup>
              </SelectContent>
            </Select>
          </div>
        )}

        <DialogFooter className="gap-2.5 mt-4 pt-3 border-t">
          <Button type="button" variant="outline" onClick={onClose} disabled={isPending}>
            Cancel
          </Button>
          {deactivatedVehicleMatch ? (
            <Button
              type="button"
              onClick={handleRestoreFoundVehicle}
              disabled={isPending}
              className="group gap-2 font-medium cursor-pointer"
            >
              {reactivateMutation.isPending ? (
                <>
                  <Spinner data-icon="inline-start" />
                  Reactivating Vehicle...
                </>
              ) : (
                <>
                  <RotateCcw className="size-4" />
                  Restore Vehicle
                </>
              )}
            </Button>
          ) : (
            <Button type="submit" disabled={isPending} className="font-medium cursor-pointer">
              {isPending ? (
                <>
                  <Spinner data-icon="inline-start" />
                  {isEditing ? 'Saving...' : 'Adding...'}
                </>
              ) : (
                <>{isEditing ? 'Save Vehicle' : 'Add Vehicle'}</>
              )}
            </Button>
          )}
        </DialogFooter>
      </form>
    </>
  )
}

export function VehicleModal({ vehicle, open, onClose }: VehicleModalProps) {
  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <DialogContent className="sm:max-w-[480px]">
        {open && (
          <VehicleFormContent
            key={vehicle ? `vehicle-${vehicle.id}` : 'new-vehicle'}
            vehicle={vehicle}
            onClose={onClose}
          />
        )}
      </DialogContent>
    </Dialog>
  )
}

