import { formatProductUnit } from '@/lib/product-unit'
import { useMemo, useState } from 'react'
import {
  ArrowLeft,
  Boxes,
  ChevronRight,
  MapPin,
  Package,
  Phone,
  Search,
  Settings2,
  Warehouse as WarehouseIcon,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { DataTable, type ColumnDef } from '@/components/ui/data-table'
import { OverflowValue } from '@/components/ui/OverflowValue'
import { useWarehouseStock } from '@/features/logistics/stock-items.hooks'
import { formatStockCents, parseStockCents, stockSortKey } from '@/features/logistics/stock-display'
import type { StockItemWithInventoryItem } from '@/features/logistics/stock-items.types'
import type { Warehouse } from '@/features/logistics/warehouses.types'
import { getErrorMessage } from '@/lib/api-client'
import { stockConditionForItem, stockConditionRank } from '@/features/logistics/stock-warnings'
import { StockIndicator } from '@/components/inventory/StockIndicator'
import { cn } from '@/lib/utils'
import { StockConditionReportModal } from '@/components/inventory/StockConditionReportModal'
import { useAuth } from '@/features/auth/AuthContext'
import { ReorderThresholdModal } from './ReorderThresholdModal'

type StockRow = {
  stock: StockItemWithInventoryItem
  quantityCents: bigint | null
  availableCents: bigint | null
  quarantinedCents: bigint | null
}

export function WarehouseInventory({
  warehouse,
  onBack,
}: {
  warehouse: Warehouse
  onBack: () => void
}) {
  const stockQuery = useWarehouseStock(warehouse.id)
  const { isAdmin, isManager, isStaff } = useAuth()
  const [reportOpen, setReportOpen] = useState(false)
  const [thresholdStock, setThresholdStock] = useState<StockItemWithInventoryItem | null>(null)
  const [search, setSearch] = useState('')
  const rows = useMemo<StockRow[]>(
    () =>
      (stockQuery.data ?? [])
        .map((stock) => ({
          stock,
          quantityCents: parseStockCents(stock.quantity),
          availableCents: parseStockCents(stock.availableQuantity),
          quarantinedCents: parseStockCents(stock.quarantinedQuantity),
        }))
        .sort(
          (a, b) =>
            stockConditionRank[stockConditionForItem(a.stock)] -
              stockConditionRank[stockConditionForItem(b.stock)] ||
            (a.stock.inventoryItem?.name ?? '').localeCompare(b.stock.inventoryItem?.name ?? '') ||
            a.stock.id - b.stock.id,
        ),
    [stockQuery.data],
  )
  const filteredRows = useMemo(() => {
    const term = search.trim().toLowerCase()
    return term
      ? rows.filter(({ stock }) =>
          String(stock.inventoryItem?.name ?? '')
            .toLowerCase()
            .includes(term),
        )
      : rows
  }, [rows, search])
  const summaryMetrics = [
    { label: 'Stock records', value: rows.length.toLocaleString(), unit: 'records', icon: Boxes },
    {
      label: 'Products',
      value: new Set(rows.map((row) => row.stock.inventoryItemId)).size.toLocaleString(),
      unit: 'products',
      icon: Package,
    },
  ]

  const columns = useMemo<ColumnDef<StockRow>[]>(
    () => [
      {
        id: 'product',
        header: 'Product',
        width: '36%',
        sortable: true,
        sortKey: (row) => row.stock.inventoryItem?.name ?? '',
        cell: ({ row }) => (
          <div
            className={cn(
              'relative flex min-w-0 flex-col gap-0.5',
              (isAdmin || isManager) && 'pr-8',
            )}
          >
            <OverflowValue
              value={row.stock.inventoryItem?.name || 'Product unavailable'}
              className="whitespace-normal text-sm font-medium leading-5 [overflow-wrap:anywhere]"
            />
            <span className="text-xs text-muted-foreground">
              {formatProductUnit(row.stock.inventoryItem?.unit) || 'Unit unavailable'}
            </span>
            {(isAdmin || isManager) && (
              <Button
                variant="ghost"
                size="icon"
                className="absolute right-0 top-0 size-8"
                title="Stock Alert Settings"
                onClick={() => setThresholdStock(row.stock)}
                aria-label={`Stock Alert Settings for ${row.stock.inventoryItem?.name ?? 'product'}`}
              >
                <Settings2 className="size-3.5" />
              </Button>
            )}
          </div>
        ),
      },
      {
        id: 'quantity',
        header: 'Physical',
        width: '18%',
        align: 'right',
        sortable: true,
        sortKey: (row) => stockSortKey(row.quantityCents),
        cell: ({ row }) => (
          <OverflowValue
            value={formatStockCents(row.quantityCents)}
            fullValue={row.quantityCents === null ? 'Unavailable' : undefined}
            tooltipSuffix={formatProductUnit(row.stock.inventoryItem?.unit)}
            className="text-right text-sm tabular-nums"
          />
        ),
      },
      {
        id: 'available',
        header: 'Available',
        width: '22%',
        align: 'right',
        sortable: true,
        sortKey: (row) => stockSortKey(row.availableCents),
        cell: ({ row }) => {
          const condition = stockConditionForItem(row.stock)
          const warning =
            condition === 'OUT' ? 'Out of stock' : condition === 'LOW' ? 'Low stock' : null
          return (
            <div
              className={cn(
                'flex min-w-0 items-center justify-end gap-1.5',
                condition === 'OUT' && 'text-destructive',
                condition === 'LOW' && 'text-status-warning-foreground',
              )}
            >
              <StockIndicator
                condition={condition}
                label={`${warning}: ${row.stock.inventoryItem?.name ?? 'Product'} in ${warehouse.name}`}
              />
              <OverflowValue
                value={formatStockCents(row.availableCents)}
                fullValue={row.availableCents === null ? 'Unavailable' : undefined}
                tooltipSuffix={formatProductUnit(row.stock.inventoryItem?.unit)}
                className="text-right text-sm font-medium tabular-nums"
              />
            </div>
          )
        },
      },
      {
        id: 'quarantined',
        header: 'Quarantined',
        width: '24%',
        align: 'right',
        sortable: true,
        sortKey: (row) => stockSortKey(row.quarantinedCents),
        cell: ({ row }) =>
          row.quarantinedCents !== null && row.quarantinedCents > 0n ? (
            <Badge
              variant="outline"
              className="max-w-full border-status-warning-foreground/20 bg-status-warning text-status-warning-foreground tabular-nums [overflow-wrap:anywhere]"
            >
              {formatStockCents(row.quarantinedCents)}{' '}
              {formatProductUnit(row.stock.inventoryItem?.unit)}
            </Badge>
          ) : (
            <OverflowValue
              value={formatStockCents(row.quarantinedCents)}
              fullValue={row.quarantinedCents === null ? 'Unavailable' : undefined}
              className="text-right text-sm text-muted-foreground tabular-nums"
            />
          ),
      },
    ],
    [warehouse.name, isAdmin, isManager],
  )

  return (
    <div className="flex flex-col gap-6">
      <header>
        <nav
          aria-label="Breadcrumb"
          className="mb-2 flex min-w-0 items-center gap-1 text-xs text-muted-foreground"
        >
          <Button
            variant="secondary"
            size="sm"
            onClick={onBack}
            className="h-11 min-h-11 gap-2 border border-border px-3 text-sm font-medium"
          >
            <ArrowLeft className="size-4" />
            Back to Warehouses
          </Button>
          <ChevronRight className="size-3.5 shrink-0" />
          <OverflowValue value={warehouse.name} className="font-semibold text-foreground" />
        </nav>
        <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-start">
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
              <h1 className="flex min-w-0 max-w-full items-center gap-2 text-2xl font-semibold">
                <WarehouseIcon className="size-5 shrink-0 text-muted-foreground" />
                <OverflowValue value={warehouse.name} className="font-semibold" />
              </h1>
              <Badge
                variant="outline"
                className={
                  warehouse.isActive === false
                    ? 'border-status-warning-foreground/30 text-status-warning-foreground'
                    : 'border-status-success-foreground/30 text-status-success-foreground'
                }
              >
                {warehouse.isActive === false ? 'Archived · View only' : 'Active'}
              </Badge>
            </div>
            <div className="mt-1.5 flex flex-wrap items-center gap-x-5 gap-y-1 text-xs text-muted-foreground">
              <span className="flex min-w-0 max-w-full items-center gap-1.5">
                <MapPin className="size-3.5 shrink-0" />
                <OverflowValue value={warehouse.address} />
              </span>
              {warehouse.contactNumber && (
                <span className="flex min-w-0 max-w-full items-center gap-1.5">
                  <Phone className="size-3.5 shrink-0" />
                  <OverflowValue value={warehouse.contactNumber} />
                </span>
              )}
            </div>
          </div>
          <section aria-label="Warehouse stock summary" className="grid grid-cols-2 gap-3">
            {summaryMetrics.map(({ label, value, unit, icon: Icon }) => (
              <div
                key={label}
                className="min-w-0 rounded-lg border border-border bg-card px-4 py-3 lg:w-44"
              >
                <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                  <Icon className="size-3.5 shrink-0 text-muted-foreground" />
                  <span>{label}</span>
                </div>
                <p className="mt-1 flex min-w-0 items-center text-2xl font-semibold tabular-nums leading-none">
                  <OverflowValue
                    value={stockQuery.isLoading || stockQuery.isError ? '—' : value}
                    tooltipSuffix={unit}
                  />
                  <span className="ml-1 text-xs font-normal text-muted-foreground">{unit}</span>
                </p>
              </div>
            ))}
          </section>
        </div>
      </header>

      <section
        aria-label={`Inventory in ${warehouse.name}`}
        className="overflow-hidden rounded-lg border border-border bg-card"
      >
        {(isAdmin || isManager || isStaff) && (
          <div className="flex justify-end border-b border-border px-4 py-3">
            <Button
              onClick={() => setReportOpen(true)}
              disabled={stockQuery.isLoading || stockQuery.isError}
            >
              Report Stock Condition
            </Button>
          </div>
        )}
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
          <h3 className="flex min-w-0 max-w-full items-center gap-1 text-base font-semibold">
            <span className="shrink-0">Inventory in</span>
            <OverflowValue value={warehouse.name} className="font-semibold" />
          </h3>
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
            <Input
              aria-label="Search warehouse products"
              placeholder="Search product..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              className="h-9 pl-9 text-[13px]"
            />
          </div>
        </div>
        {stockQuery.isError ? (
          <div role="alert" className="p-4 text-xs text-destructive">
            Warehouse stock could not be loaded: {getErrorMessage(stockQuery.error)}
            <Button variant="link" size="sm" onClick={() => void stockQuery.refetch()}>
              Retry
            </Button>
          </div>
        ) : (
          <DataTable
            data={filteredRows}
            columns={columns}
            getRowKey={(row) => row.stock.id}
            rowClassName={(row) => {
              const condition = stockConditionForItem(row.stock)
              return condition === 'OUT'
                ? 'bg-destructive/5 hover:bg-destructive/10'
                : condition === 'LOW'
                  ? 'bg-status-warning/50 hover:bg-status-warning'
                  : ''
            }}
            isLoading={stockQuery.isLoading}
            loadingMessage="Loading warehouse inventory..."
            emptyContent={
              <div className="px-4 py-12 text-center text-xs text-muted-foreground">
                {search
                  ? 'No products match your search.'
                  : 'No stock records for this warehouse yet.'}
              </div>
            }
            pageSizeOptions={[10, 25, 50, 100]}
            className="rounded-none border-0 shadow-none"
            tableClassName="min-w-[480px] table-fixed w-full [&_tbody_tr]:h-14 [&_tbody_td]:py-2"
          />
        )}
      </section>
      {reportOpen && (
        <StockConditionReportModal
          open
          onClose={() => setReportOpen(false)}
          stocks={(stockQuery.data ?? []).map((stock) => ({ ...stock, warehouse }))}
          stocksLoading={stockQuery.isLoading}
          stocksError={stockQuery.isError}
        />
      )}
      {thresholdStock && (
        <ReorderThresholdModal
          open
          stock={thresholdStock}
          productName={thresholdStock.inventoryItem.name}
          warehouseName={warehouse.name}
          onClose={() => setThresholdStock(null)}
        />
      )}
    </div>
  )
}

