  let products = 0
  for (const item of items) {
    const quantity = parseStockCents(item.quantity)
    if (quantity === null) {
      throw new Error('The warehouse stock count could not be verified. Please try again.')
    }
    if (quantity > 0n) {
      products += 1
    }
  }
  return { products, hasStock: products > 0 }
}

