          )}
        </DialogFooter>
      </form>
    </>
  )
}

export function WarehouseModal({ warehouse, open, onClose }: WarehouseModalProps) {
  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
