import { useRef, useState } from 'react'
import { ChevronDown } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { OverflowValue } from '@/components/ui/OverflowValue'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { formatOrderCurrency, parseOrderDecimal } from '@/lib/order-amounts'
import {
  discountFields,
  lineDiscountError,
  orderLineAmounts,
  savedOrderTotals,
  type LineDiscount,
  type PricedOrderLine,
  type SavedLineAmounts,
} from '@/lib/order-line-pricing'

export function OrderLineDiscount({
  id,
  name,
  value,
  line,
  onChange,
  fixedDisabled = false,
}: {
  id: string
  name: string
  value: LineDiscount
  line: Pick<PricedOrderLine, 'quantity' | 'unitPrice'>
  onChange: (value: LineDiscount) => void
  fixedDisabled?: boolean
}) {
  const [open, setOpen] = useState(false)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const error = lineDiscountError({ ...line, ...discountFields(value) })
  const applied = (parseOrderDecimal(value[value.type]) ?? 0n) > 0n
  const summary = error
    ? 'Review discount'
    : !applied
      ? 'Add discount'
      : value.type === 'peso'
        ? formatOrderCurrency(value.peso)
        : `${value.percentage}%`
  return (
    <div className="flex min-w-0 flex-col gap-1">
      <span aria-hidden="true" className="order-entry-mobile-label">
        Line discount
      </span>
      <OverflowValue asChild value={summary}>
        <Button
          ref={triggerRef}
          id={id}
          type="button"
          variant="outline"
          size="sm"
          aria-label={`Edit discount for ${name}`}
          aria-invalid={!!error}
          aria-describedby={error ? `${id}-error` : undefined}
          className="h-9 w-full min-w-0 px-2 text-xs font-normal tabular-nums"
          onClick={() => setOpen(true)}
        >
          <span data-overflow-text className="min-w-0 truncate">
            {summary}
          </span>
        </Button>
      </OverflowValue>
      {error && (
        <p id={`${id}-error`} role="alert" className="text-xs text-destructive">
          {error}
        </p>
      )}
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent
          className="sm:max-w-sm"
          onCloseAutoFocus={(event) => {
            event.preventDefault()
            triggerRef.current?.focus()
          }}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && event.target instanceof HTMLInputElement) {
              event.preventDefault()
              event.stopPropagation()
              if (!error) setOpen(false)
            }
          }}
        >
          <DialogHeader>
            <DialogTitle>Line discount</DialogTitle>
            <DialogDescription className="[overflow-wrap:anywhere]">
              {name}. Choose a percentage or a fixed peso amount for this line.
            </DialogDescription>
          </DialogHeader>
          <div className="flex min-w-0 items-start gap-2">
            <Select
              value={value.type}
              onValueChange={(type) => onChange({ ...value, type: type as LineDiscount['type'] })}
            >
              <SelectTrigger
                aria-label={`Discount type for ${name}`}
                className="h-10 w-24 shrink-0"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  <SelectItem value="percentage">Percent</SelectItem>
                  <SelectItem value="peso" disabled={fixedDisabled}>
                    Pesos
                  </SelectItem>
                </SelectGroup>
              </SelectContent>
            </Select>
            <Input
              id={`${id}-value`}
              aria-label={`Line discount for ${name}`}
              type="text"
              inputMode="decimal"
              autoComplete="off"
              placeholder="0"
              value={value[value.type]}
              disabled={fixedDisabled && value.type === 'peso'}
              onChange={(event) => onChange({ ...value, [value.type]: event.target.value })}
              aria-invalid={!!error}
              aria-describedby={error ? `${id}-editor-error` : undefined}
              className="min-w-0 text-right tabular-nums"
            />
          </div>
          {error && (
            <p id={`${id}-editor-error`} role="alert" className="text-sm text-destructive">
              {error}
            </p>
          )}
          <div className="flex flex-wrap justify-end gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                onChange({ type: 'percentage', percentage: '', peso: '' })
                setOpen(false)
              }}
            >
              Remove discount
            </Button>
            <Button type="button" disabled={!!error} onClick={() => setOpen(false)}>
              Done
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

export function OrderLineAmounts({
