      <dd>{formatOrderCurrency(amounts?.vat ?? null)}</dd>
      <dt className="pt-1 font-semibold">Total</dt>
      <dd className="pt-1 font-semibold">{formatOrderCurrency(amounts?.total ?? null)}</dd>
    </dl>
  )
