import { PageHeader, PageToolbar } from '@/components/ui/ManagementPage'
import { SalesOrderCancelModal } from './SalesOrderCancelModal'
import { useState, useMemo } from 'react'
import { CheckCircle2, Eye, MoreHorizontal, Plus, ReceiptText, Search, XCircle } from 'lucide-react'
import { Card } from '@/components/ui/card'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { StatusTabNav } from '@/components/ui/StatusTabNav'
import { OrderModal, type OrderFormValues } from './OrderModal'
import { buildSalesOrderPayload } from '@/features/crm/sales-order-entry.utils'
import { OrderDetailDrawer } from './OrderDetailDrawer'
import { QuickDispatchModal } from './QuickDispatchModal'
import { DeliveryDetailModal } from '@/components/deliveries/shared/DeliveryDetailModal'
import { useClients } from '@/features/crm/clients.hooks'
import { useProducts } from '@/features/products/products.hooks'
import { useWarehouses } from '@/features/logistics/warehouses.hooks'
import { useStockItems } from '@/features/logistics/stock-items.hooks'
import { useDeliveryVehicles } from '@/features/logistics/delivery-vehicles.hooks'
import { useEmployees } from '@/features/staffing/staffing.hooks'
import { useOutgoingDeliveries } from '@/features/logistics/outgoing-deliveries.hooks'
import { CompleteDeliveryModal } from '@/components/deliveries/shared/CompleteDeliveryModal'
import {
  useSalesOrders,
  SALES_ORDERS_QUERY_KEY,
  useCreateSalesOrder,
  useConfirmSalesOrder,
  useCancelSalesOrder,
  useSalesOrderById,
  useUpdateSalesOrderDraft,
} from '@/features/crm/sales-orders.hooks'
import { toast } from 'sonner'
import { useQueryClient } from '@tanstack/react-query'
import { useAuth } from '@/features/auth/AuthContext'
import type { SalesOrderRecord } from '@/features/crm/sales-orders.types'
import { fetchSalesOrderByIdApi } from '@/features/crm/sales-orders.api'
import { getSalesOrderDeliveryDisplay } from '@/features/crm/sales-orders.presentation'
import { getErrorMessage } from '@/lib/api-client'
import { cn } from '@/lib/utils'
import { DataTable, type ColumnDef } from '@/components/ui/data-table'
import { OverflowValue } from '@/components/ui/OverflowValue'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import type { OutgoingDeliveryRecord } from '@/features/logistics/outgoing-deliveries.types'

export type OrderTabFilter = 'Active' | 'Completed' | 'Cancelled'

export type OrdersViewProps = {
  onNavigateToPurchases?: () => void
  onNavigateToDeliveries?: (
    tab?: 'schedule' | 'status' | 'completed' | 'incoming' | 'outgoing' | 'history',
    salesOrderId?: number,
    arrange?: boolean,
  ) => void
  onNavigateToInventory?: () => void
}

type SalesOrderPrimaryAction =
  | 'confirm'
  | 'prepare-delivery'
  | 'continue-delivery'
  | 'view-delivery'
  | 'confirm-arrival'
  | 'view-order'

function getSalesOrderPrimaryAction(
  order: SalesOrderRecord,
  delivery?: OutgoingDeliveryRecord,
): SalesOrderPrimaryAction {
  if (order.status === 'DELIVERED' || order.status === 'CANCELLED') return 'view-order'
  if (order.status === 'DRAFT') return 'confirm'
  if (delivery?.status === 'DISPATCHED') return 'confirm-arrival'
  if (delivery && delivery.status !== 'DELIVERED') return 'view-delivery'
  if (order.status === 'PARTIALLY_DELIVERED') return 'continue-delivery'
  return 'prepare-delivery'
}

export function OrdersView({
  onNavigateToPurchases,
  onNavigateToDeliveries,
  onNavigateToInventory,
}: OrdersViewProps = {}) {
  const queryClient = useQueryClient()
  const [searchTerm, setSearchTerm] = useState('')
  const [activeStatus, setActiveStatus] = useState<OrderTabFilter>('Active')

  // Modals & Drawers state
  const [isOrderModalOpen, setIsOrderModalOpen] = useState(false)
  const [editingOrderId, setEditingOrderId] = useState<number>()
  const [selectedOrderRecord, setSelectedOrderRecord] = useState<SalesOrderRecord | null>(null)
  const [isDetailDrawerOpen, setIsDetailDrawerOpen] = useState(false)
  const [dispatchOrder, setDispatchOrder] = useState<SalesOrderRecord | null>(null)
  const [deliveryToComplete, setDeliveryToComplete] = useState<number | null>(null)
  const [deliveryToView, setDeliveryToView] = useState<number | null>(null)
  const [orderToCancel, setOrderToCancel] = useState<SalesOrderRecord | null>(null)

  // Real backend queries
  const ordersQuery = useSalesOrders()
  const { data: salesOrders = [], isLoading: isLoadingOrders } = ordersQuery
  const { data: clients = [] } = useClients()
  const productsQuery = useProducts()
  const { data: products = [] } = productsQuery
  const { data: warehouses = [] } = useWarehouses()
  const stockQuery = useStockItems()
  const { data: stockItems = [] } = stockQuery
  const { data: vehicles = [] } = useDeliveryVehicles({ includeInactive: 'true' })
  const { data: employees = [] } = useEmployees({ includeInactive: 'true' })
  const { data: outgoingDeliveries = [] } = useOutgoingDeliveries()

  // Mutations
  const createOrderMutation = useCreateSalesOrder({ notifySuccess: false })
  const confirmOrderMutation = useConfirmSalesOrder()
  const cancelOrderMutation = useCancelSalesOrder()
  const updateDraftMutation = useUpdateSalesOrderDraft()
  const editingOrderQuery = useSalesOrderById(editingOrderId)

  const { user, isAdmin, isManager } = useAuth()
  const canManage = isAdmin || isManager
  const cashier = user?.fullName || user?.email || 'Current User'

  // Lookups
  const clientMap = useMemo(() => new Map(clients.map((c) => [c.id, c])), [clients])
  const productMap = useMemo(() => new Map(products.map((p) => [p.id, p])), [products])

  // Sync selectedOrderRecord if the list updates
  const activeSelectedOrder = useMemo(() => {
    if (!selectedOrderRecord) return null
    return salesOrders.find((o) => o.id === selectedOrderRecord.id) || selectedOrderRecord
  }, [salesOrders, selectedOrderRecord])

  // Live tab counters
  const statusCount = (status: OrderTabFilter) => {
    if (status === 'Active') {
      return salesOrders.filter((o) =>
        ['DRAFT', 'CONFIRMED', 'PARTIALLY_DELIVERED'].includes(o.status),
      ).length
    }
    if (status === 'Completed') {
      return salesOrders.filter((o) => o.status === 'DELIVERED').length
    }
    if (status === 'Cancelled') {
      return salesOrders.filter((o) => o.status === 'CANCELLED').length
    }
    return 0
  }

  // Filter orders by active tab and search
  const filteredOrders = useMemo(() => {
    return salesOrders.filter((order) => {
      let matchesTab = false
      if (activeStatus === 'Active') {
        matchesTab = ['DRAFT', 'CONFIRMED', 'PARTIALLY_DELIVERED'].includes(order.status)
      } else if (activeStatus === 'Completed') {
        matchesTab = order.status === 'DELIVERED'
      } else if (activeStatus === 'Cancelled') {
        matchesTab = order.status === 'CANCELLED'
      }

      if (!matchesTab) return false

      if (!searchTerm.trim()) return true
      const term = searchTerm.toLowerCase().trim()
      const client = clientMap.get(order.clientId)
      const clientName = client?.name.toLowerCase() || ''
      const orderNo = order.orderNumber.toLowerCase()
      const address = order.deliveryAddress.toLowerCase()

      const hasMatchingProduct = (order.items || []).some((item) => {
        const prod = productMap.get(item.inventoryItemId)
        return prod?.name.toLowerCase().includes(term) || false
      })

      return (
        orderNo.includes(term) ||
        clientName.includes(term) ||
        address.includes(term) ||
        hasMatchingProduct
      )
    })
  }, [salesOrders, activeStatus, searchTerm, clientMap, productMap])

  // Return the saved identity so the composer can confirm or retry that exact draft.
  const handleSaveOrder = async (
    values: OrderFormValues,
    intent: 'draft' | 'confirm' = 'draft',
  ) => {
    const order = await createOrderMutation.mutateAsync(buildSalesOrderPayload(values))
    if (intent === 'draft')
      toast.success('Draft saved', { description: `Sales order ${order.orderNumber}.` })
    return order
  }

  // Confirm order action
  const handleConfirmOrder = async (order: SalesOrderRecord) => {
    if (!canManage || confirmOrderMutation.isPending) return
    try {
      await confirmOrderMutation.mutateAsync(order.id)
    } catch (err) {
      toast.error(getErrorMessage(err))
    }
  }

  // Cancellation is reviewed in the application dialog before the API request.
  const handleCancelOrder = (order: SalesOrderRecord) => {
    if (canManage && !cancelOrderMutation.isPending) setOrderToCancel(order)
  }

  const orderRows = filteredOrders.map((order) => {
    const items = order.items || []
    const itemSummary = items
      .map((item) => {
        const product = productMap.get(item.inventoryItemId)
        return `${product?.name || `Product #${item.inventoryItemId}`} ×${item.quantity}`
      })
      .join(', ')
    const itemLabel = items.length === 1 ? itemSummary : `${items.length} items`
    const orderTotal = items.reduce((sum, item) => sum + Number(item.totalAmount), 0)
    const activeDelivery = outgoingDeliveries.find(
      (delivery) => delivery.salesOrderId === order.id && delivery.status !== 'CANCELLED',
    )
    const deliveryDisplay = getSalesOrderDeliveryDisplay(order, activeDelivery, outgoingDeliveries)

    return {
      order,
      client: clientMap.get(order.clientId),
      itemSummary,
      itemLabel,
      orderTotal,
      activeDelivery,
      deliveryDisplay,
    }
  })

  const openOrderDetails = (order: SalesOrderRecord) => {
    setSelectedOrderRecord(order)
    setIsDetailDrawerOpen(true)
  }

  const editDraft = (order: SalesOrderRecord) => {
    if (!canManage || order.status !== 'DRAFT') return
    setIsDetailDrawerOpen(false)
    setEditingOrderId(order.id)
  }

  const handlePrimaryAction = (
    action: SalesOrderPrimaryAction,
    order: SalesOrderRecord,
    delivery?: OutgoingDeliveryRecord,
  ) => {
    switch (action) {
      case 'confirm':
        void handleConfirmOrder(order)
        break
      case 'prepare-delivery':
      case 'continue-delivery':
        if (onNavigateToDeliveries) onNavigateToDeliveries('outgoing', order.id)
        else setDispatchOrder(order)
        break
      case 'view-delivery':
        if (delivery) setDeliveryToView(delivery.id)
        break
      case 'confirm-arrival':
        if (!delivery) break
        if (onNavigateToDeliveries) onNavigateToDeliveries('outgoing', order.id)
        else setDeliveryToComplete(delivery.id)
        break
      case 'view-order':
        openOrderDetails(order)
        break
    }
  }

  const salesOrderColumns: ColumnDef<(typeof orderRows)[number]>[] = [
    {
      id: 'order',
      header: 'Order',
      width: 145,
      className: 'min-w-[145px]',
      cell: ({ row: { order } }) => (
        <div className="flex flex-col gap-1">
          <span className="whitespace-nowrap text-sm font-medium text-foreground">
            {order.orderNumber}
          </span>
          {['DRAFT', 'CONFIRMED'].includes(order.status) && (
            <span className="text-xs text-muted-foreground">
              {order.status === 'DRAFT' ? 'Draft' : 'Confirmed'}
            </span>
          )}
        </div>
      ),
    },
    {
      id: 'customer',
      header: 'Customer',
      width: 210,
      className: 'min-w-[180px] max-w-[250px]',
      cell: ({ row: { order, client } }) => (
        <div className="flex min-w-0 flex-col gap-1">
          <span
            className="truncate text-sm font-medium text-foreground"
            title={client?.name || `Customer #${order.clientId}`}
          >
            {client?.name || `Customer #${order.clientId}`}
          </span>
          <span className="truncate text-xs text-muted-foreground" title={order.deliveryAddress}>
            {order.deliveryAddress || 'No address specified'}
          </span>
        </div>
      ),
    },
    {
      id: 'items',
      header: 'Items',
      width: 165,
      className: 'hidden max-w-[220px] lg:table-cell',
      headerClassName: 'hidden lg:table-cell',
      cell: ({ row: { order, itemLabel, itemSummary } }) => {
        const item = order.items?.length === 1 ? order.items[0] : undefined
        const itemName = item
          ? productMap.get(item.inventoryItemId)?.name || `Product #${item.inventoryItemId}`
          : itemLabel || 'No items'
        if ((order.items?.length ?? 0) > 1) {
          return (
            <OverflowValue
              value={itemName}
              fullValue={itemSummary}
              showFullValueOnHover
              className="text-foreground"
            />
          )
        }
        return (
          <span className="block truncate text-foreground" title={itemSummary}>
            {itemName}
            {item && <span className="font-normal text-muted-foreground"> ×{item.quantity}</span>}
          </span>
        )
      },
    },
    {
      id: 'total',
      header: 'Total',
      width: 110,
      align: 'right',
      className: 'whitespace-nowrap tabular-nums text-foreground',
      cell: ({ row: { orderTotal } }) =>
        `₱${orderTotal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`,
    },
    {
      id: 'delivery',
      header: 'Delivery',
      width: 155,
      className: 'whitespace-nowrap',
      cell: ({ row: { deliveryDisplay } }) => (
        <Badge
          variant="outline"
          className={cn('whitespace-nowrap px-2', deliveryDisplay.badgeClassName)}
        >
          {deliveryDisplay.label}
        </Badge>
      ),
    },
    {
      id: 'action',
      header: 'Action',
      width: 185,
      align: 'right',
      className: 'whitespace-nowrap',
      cell: ({ row: { order, activeDelivery } }) => {
        const primaryAction = canManage
          ? getSalesOrderPrimaryAction(order, activeDelivery)
          : 'view-order'
        const primaryLabel: Record<SalesOrderPrimaryAction, string> = {
          confirm: 'Confirm',
          'prepare-delivery': 'Outgoing Deliveries',
          'continue-delivery': 'Outgoing Deliveries',
          'view-delivery': 'View Delivery',
          'confirm-arrival': 'Confirm Arrival',
          'view-order': 'View',
        }
        const primaryVariant = {
          confirm: 'default',
          'prepare-delivery': 'default',
          'continue-delivery': 'default',
          'view-delivery': 'ghost',
          'confirm-arrival': 'secondary',
          'view-order': 'ghost',
        } as const
        const showViewOrder = primaryAction !== 'view-order'
        const isViewOrder = primaryAction === 'view-order'
        const showViewDelivery = Boolean(activeDelivery) && primaryAction !== 'view-delivery'
        const canCancelOrder =
          canManage && (order.status === 'DRAFT' || order.status === 'CONFIRMED')

        return (
          <div
            className="flex items-center justify-end gap-1"
            onClick={(event) => event.stopPropagation()}
          >
            <Button
              size={isViewOrder ? 'icon' : 'sm'}
              variant={primaryVariant[primaryAction]}
              className={isViewOrder ? 'size-8 pointer-coarse:size-11' : undefined}
              aria-label={isViewOrder ? `View sales order ${order.orderNumber}` : undefined}
              title={isViewOrder ? 'View order' : undefined}
              disabled={primaryAction === 'confirm' && confirmOrderMutation.isPending}
              onClick={() => handlePrimaryAction(primaryAction, order, activeDelivery)}
            >
              {isViewOrder ? <Eye aria-hidden="true" /> : primaryLabel[primaryAction]}
            </Button>

            {(showViewOrder || showViewDelivery || canCancelOrder) && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="size-8 text-muted-foreground"
                    aria-label={`More actions for ${order.orderNumber}`}
                    title="More actions"
                  >
                    <MoreHorizontal />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-44">
                  <DropdownMenuGroup>
                    {canManage && order.status === 'DRAFT' && (
                      <DropdownMenuItem onSelect={() => editDraft(order)}>
                        Edit Draft
                      </DropdownMenuItem>
                    )}
                    {showViewOrder && (
                      <DropdownMenuItem onSelect={() => openOrderDetails(order)}>
                        <Eye className="mr-2 size-3.5" />
                        View Order
                      </DropdownMenuItem>
                    )}
                    {showViewDelivery && activeDelivery && (
                      <DropdownMenuItem onSelect={() => setDeliveryToView(activeDelivery.id)}>
                        View Delivery
                      </DropdownMenuItem>
                    )}
                    {canCancelOrder && (
                      <>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          disabled={cancelOrderMutation.isPending}
                          onSelect={() => void handleCancelOrder(order)}
                          className="text-destructive focus:text-destructive"
                        >
                          Cancel Order
                        </DropdownMenuItem>
                      </>
                    )}
                  </DropdownMenuGroup>
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </div>
        )
      },
    },
  ]

  return (
    <div className="flex min-w-0 flex-col gap-4">
      <PageHeader description="Create and track customer orders and deliveries.">
        Sales Orders
      </PageHeader>
      <StatusTabNav
        activeTab={activeStatus}
        onTabChange={(tab) => setActiveStatus(tab as OrderTabFilter)}
        tabs={[
          {
            value: 'Active',
            label: 'Active Orders',
            count: statusCount('Active'),
            icon: <CheckCircle2 className="size-3.5" />,
            accent: 'green',
          },
          {
            value: 'Completed',
            label: 'Completed Orders',
            count: statusCount('Completed'),
            icon: <CheckCircle2 className="size-3.5" />,
            accent: 'blue',
          },
          {
            value: 'Cancelled',
            label: 'Cancelled Orders',
            count: statusCount('Cancelled'),
            icon: <XCircle className="size-3.5" />,
            accent: 'red',
          },
        ]}
      />

      {/* Top Controls */}
      <PageToolbar>
        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
          <Input
            aria-label="Search orders"
            placeholder="Search order # or customer..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 h-9 text-ui"
          />
        </div>

        <Button
          size="sm"
          onClick={() => {
            setIsOrderModalOpen(true)
          }}
          disabled={!canManage}
          className="gap-1.5 text-ui"
        >
          <Plus className="size-4" />
          Create Sales Order
        </Button>
      </PageToolbar>

      {/* Orders Table */}
      {ordersQuery.isError ? (
        <Alert variant="destructive">
          <AlertDescription>
            Sales orders could not be loaded. {getErrorMessage(ordersQuery.error)}
            <Button
              variant="outline"
              size="sm"
              className="ml-2"
              onClick={() => void ordersQuery.refetch()}
              disabled={ordersQuery.isFetching}
            >
              {ordersQuery.isFetching ? 'Retrying...' : 'Retry'}
            </Button>
          </AlertDescription>
        </Alert>
      ) : isLoadingOrders ? (
        <DataTable
          appearance="management"
          data={orderRows}
          columns={salesOrderColumns}
          getRowKey={({ order }) => order.id}
          isLoading
          loadingMessage="Loading sales orders..."
          pageSize={10}
          pageSizeOptions={[10, 25, 50, 100]}
          tableClassName="table-fixed min-w-[760px] lg:min-w-[960px]"
        />
      ) : filteredOrders.length === 0 ? (
        <Card className="flex min-h-[360px] items-center justify-center border-border bg-card shadow-none">
          <div className="flex flex-col items-center justify-center text-center">
            <ReceiptText className="size-8 text-muted-foreground" />
            <span className="text-sm font-semibold text-foreground mt-2">
              {searchTerm.trim()
                ? `No ${activeStatus.toLowerCase()} orders match "${searchTerm.trim()}"`
                : `No ${activeStatus.toLowerCase()} orders found`}
            </span>
            <p className="text-xs text-muted-foreground mt-1 max-w-xs">
              {searchTerm.trim()
                ? 'Try searching with a different order number, customer name, or item.'
                : activeStatus === 'Active'
                  ? 'Click "Create Sales Order" to record your first customer purchase!'
                  : 'Orders moved into this status will appear here.'}
            </p>
          </div>
        </Card>
      ) : (
        <DataTable
          appearance="management"
          data={orderRows}
          columns={salesOrderColumns}
          getRowKey={({ order }) => order.id}
          pageSize={10}
          pageSizeOptions={[10, 25, 50, 100]}

          onRowClick={({ order }) => openOrderDetails(order)}
          tableClassName="table-fixed min-w-[760px] lg:min-w-[960px]"
        />
      )}

      {orderToCancel && (
        <SalesOrderCancelModal
          order={orderToCancel}
          onClose={() => setOrderToCancel(null)}
          onConfirm={(id) => {
            if (!canManage) throw new Error('You do not have permission to cancel orders.')
            return cancelOrderMutation.mutateAsync(id)
          }}
        />
      )}

      {/* Order Creation Modal */}
      {isOrderModalOpen && canManage && (
        <OrderModal
          open
          onClose={() => setIsOrderModalOpen(false)}
          onSubmit={handleSaveOrder}
          onConfirm={(id) => confirmOrderMutation.mutateAsync(id)}
          clients={clients}
          products={products}
          catalogState={{
            productsLoading: productsQuery.isLoading,
            stockLoading: stockQuery.isLoading,
            productsError: productsQuery.error ? getErrorMessage(productsQuery.error) : undefined,
            stockError: stockQuery.error ? getErrorMessage(stockQuery.error) : undefined,
            onRetry: () => {
              void productsQuery.refetch()
              void stockQuery.refetch()
            },
          }}
          warehouses={warehouses}
          stockItems={stockItems}
          cashier={cashier}
          onNavigateToPurchases={onNavigateToPurchases}
          onNavigateToDeliveries={onNavigateToDeliveries}
          onNavigateToInventory={onNavigateToInventory}
        />
      )}

      {editingOrderId !== undefined &&
        canManage &&
        (editingOrderQuery.data ? (
          <OrderModal
            key={editingOrderId}
            open
            draftOrder={editingOrderQuery.data}
            onClose={() => setEditingOrderId(undefined)}
            onSubmit={handleSaveOrder}
            onUpdateDraft={(id, payload) => updateDraftMutation.mutateAsync({ id, payload })}
            onLoadLatest={(id) =>
              queryClient.fetchQuery({
                queryKey: [...SALES_ORDERS_QUERY_KEY, 'id', id],
                queryFn: () => fetchSalesOrderByIdApi(id),
                staleTime: 0,
              })
            }
            onConfirm={(id) => confirmOrderMutation.mutateAsync(id)}
            clients={clients}
            products={products}
            stockItems={stockItems}
            cashier={cashier}
            catalogState={{
              productsLoading: productsQuery.isLoading,
              productsError: productsQuery.error ? getErrorMessage(productsQuery.error) : undefined,
              onRetry: () => void productsQuery.refetch(),
            }}
          />
        ) : (
          <Dialog open onOpenChange={(open) => !open && setEditingOrderId(undefined)}>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Edit Sales Order Draft</DialogTitle>
                <DialogDescription>Load the saved order before making changes.</DialogDescription>
              </DialogHeader>
              {editingOrderQuery.isPending ? (
                <p role="status">Loading sales order…</p>
              ) : (
                <Alert variant="destructive">
                  <AlertDescription>
                    {editingOrderQuery.error
                      ? getErrorMessage(editingOrderQuery.error)
                      : 'This sales order is no longer available.'}
                    <Button
                      type="button"
                      variant="outline"
                      disabled={editingOrderQuery.isFetching}
                      onClick={() => void editingOrderQuery.refetch()}
                    >
                      Retry
                    </Button>
                  </AlertDescription>
                </Alert>
              )}
            </DialogContent>
          </Dialog>
        ))}

      {deliveryToComplete !== null && <CompleteDeliveryModal key={deliveryToComplete} deliveryId={deliveryToComplete} onClose={() => setDeliveryToComplete(null)} />}
      {/* Guided Order Detail Drawer */}
      <OrderDetailDrawer
        open={isDetailDrawerOpen}
        onClose={() => {
          setIsDetailDrawerOpen(false)
          setSelectedOrderRecord(null)
        }}
        order={activeSelectedOrder}
        clients={clients}
        products={products}
        warehouses={warehouses}
        vehicles={vehicles}
        employees={employees}
        stockItems={stockItems}
        outgoingDeliveries={outgoingDeliveries}
        onConfirmed={() => setIsDetailDrawerOpen(false)}
        onEdit={editDraft}
        onArrangeDelivery={
          onNavigateToDeliveries
            ? (orderId) => onNavigateToDeliveries('outgoing', orderId, true)
            : undefined
        }
        onViewDelivery={(id) => {
          setIsDetailDrawerOpen(false)
          setDeliveryToView(id)
        }}
      />

      {deliveryToView !== null && (
        <DeliveryDetailModal
          open
          deliveryId={deliveryToView}
          onClose={() => setDeliveryToView(null)}
        />
      )}

      {/* Quick Dispatch Modal for row actions */}
      {dispatchOrder && (
        <QuickDispatchModal
          open={Boolean(dispatchOrder)}
          onClose={() => setDispatchOrder(null)}
          order={dispatchOrder}
          vehicles={vehicles}
          employees={employees}
          warehouses={warehouses}
          stockItems={stockItems}
          onSuccess={() => {
            setDispatchOrder(null)
          }}
        />
      )}
    </div>
  )
}

