    switch (action) {
      case 'confirm':
        void handleConfirmOrder(order)
        break
      case 'prepare-delivery':
      case 'continue-delivery':
        if (onNavigateToDeliveries) onNavigateToDeliveries('outgoing', order.id)
        else setDispatchOrder(order)
