import { useState, useMemo } from 'react'
import { Truck, UserRound, MapPin, AlertCircle, PackageCheck, Clock } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { useQueryClient } from '@tanstack/react-query'
import { useOutgoingDeliveries } from '@/features/logistics/outgoing-deliveries.hooks'
import { DeliveryUtils } from '@/features/logistics/delivery-utils'
import { toast } from 'sonner'
import type { SalesOrderRecord } from '@/features/crm/sales-orders.types'
import type { DeliveryVehicle } from '@/features/logistics/delivery-vehicles.types'
import type { Employee } from '@/features/staffing/staffing.types'
import type { Warehouse } from '@/features/logistics/warehouses.types'
import type { StockItem } from '@/features/logistics/stock-items.types'
import {
  createOutgoingDeliveryApi,
  scheduleOutgoingDeliveryApi,
  dispatchOutgoingDeliveryApi,
} from '@/features/logistics/outgoing-deliveries.api'
import {
  outgoingLinesForAvailableSources,
  outgoingOrderBalances,
} from '@/features/logistics/outgoing-order-balance'
import {
  DELIVERIES_QUERY_KEY,
  SALES_ORDERS_QUERY_KEY,
} from '@/features/logistics/outgoing-deliveries.hooks'
import { VEHICLES_QUERY_KEY } from '@/features/logistics/delivery-vehicles.hooks'
import { getErrorMessage } from '@/lib/api-client'

interface QuickDispatchModalProps {
  open: boolean
  onClose: () => void
  onSuccess?: () => void
  order: SalesOrderRecord
  vehicles: DeliveryVehicle[]
  employees: Employee[]
  warehouses: Warehouse[]
  stockItems: StockItem[]
}

export function QuickDispatchModal({
  open,
  onClose,
  onSuccess,
  order,
  vehicles,
  employees,
  warehouses,
  stockItems,
}: QuickDispatchModalProps) {
  const queryClient = useQueryClient()
  const { data: deliveries = [] } = useOutgoingDeliveries()
  const [selectedVehicleId, setSelectedVehicleId] = useState<string>('')
  const [selectedDriverId, setSelectedDriverId] = useState<string>('')
  const [scheduledAt, setScheduledAt] = useState<string>(() =>
    new Date(Date.now() + 30 * 60000).toISOString().slice(0, 16),
  )
  const [notes, setNotes] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMessage, setErrorMessage] = useState('')

  const balances = useMemo(
    () => outgoingOrderBalances(order, deliveries, stockItems, warehouses),
    [order, deliveries, stockItems, warehouses],
  )
  const warehouseNames = useMemo(() => {
    const stockMap = new Map(stockItems.map((stock) => [stock.id, stock]))
    const sourceIds = new Set(
      balances.flatMap((balance) =>
        outgoingLinesForAvailableSources(balance).map((line) => line.stockItemId),
      ),
    )
    return [...new Set(
      [...sourceIds]
        .map((id) => stockMap.get(id)?.warehouseId)
        .filter((id): id is number => id !== undefined)
        .map((id) => warehouses.find((warehouse) => warehouse.id === id)?.name ?? `Warehouse #${id}`),
    )]
  }, [balances, stockItems, warehouses])

  const availableVehicles = useMemo(
    () =>
      (vehicles || []).filter(
        (vehicle) => DeliveryUtils.getVehicleAvailability(vehicle, deliveries).isAvailable,
      ),
    [vehicles, deliveries],
  )

  const activeEmployees = useMemo(
    () =>
      (employees || []).filter(
        (employee) => DeliveryUtils.getDriverAvailability(employee, deliveries).isAvailable,
      ),
    [employees, deliveries],
  )

  const sourcesToDeliver = useMemo(
    () => balances.flatMap(outgoingLinesForAvailableSources),
    [balances],
  )

  const handleDispatch = async (e: React.FormEvent) => {
    e.preventDefault()
    setErrorMessage('')

    if (!selectedVehicleId) {
      setErrorMessage('Please assign an available delivery fleet vehicle.')
      return
    }

    if (!selectedDriverId) {
      setErrorMessage('Please assign an active driver or courier.')
      return
    }

    if (!availableVehicles.some((vehicle) => vehicle.id === Number(selectedVehicleId))) {
      setErrorMessage('This vehicle is no longer available. Choose another vehicle.')
      return
    }
    if (!activeEmployees.some((employee) => employee.id === Number(selectedDriverId))) {
      setErrorMessage('This driver is no longer available. Choose another driver.')
      return
    }

    if (sourcesToDeliver.length === 0) {
      setErrorMessage('No available warehouse stock remains for this order.')
      return
    }

    try {
      setIsSubmitting(true)
      const vehicleId = Number(selectedVehicleId)
      const driverId = Number(selectedDriverId)

      // Step 1: Create the outgoing delivery record tied to this sales order
      const delivery = await createOutgoingDeliveryApi({
        salesOrderId: order.id,
        deliveryVehicleId: vehicleId,
        driverEmployeeId: driverId,
        scheduledAt: scheduledAt ? new Date(scheduledAt).toISOString() : new Date().toISOString(),
        notes: notes.trim() || undefined,
        items: sourcesToDeliver,
      })

      // Step 2: Schedule the delivery
      await scheduleOutgoingDeliveryApi(delivery.id)

      // Step 3: Dispatch the vehicle & driver (sets vehicle to IN_DELIVERY, delivery to DISPATCHED)
      await dispatchOutgoingDeliveryApi(delivery.id, {
        deliveryVehicleId: vehicleId,
        driverEmployeeId: driverId,
      })

      // Invalidate queries so Order & Deliveries views refresh instantaneously
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: SALES_ORDERS_QUERY_KEY }),
        queryClient.invalidateQueries({ queryKey: DELIVERIES_QUERY_KEY }),
        queryClient.invalidateQueries({ queryKey: VEHICLES_QUERY_KEY }),
      ])

      toast.success(
        `Shipment "${delivery.deliveryNumber}" dispatched successfully for ${order.orderNumber}!`,
      )

      onSuccess?.()
      onClose()
    } catch (err) {
      setErrorMessage(getErrorMessage(err))
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <DialogContent className="max-h-[min(880px,calc(100vh-2rem))] overflow-y-auto sm:max-w-xl gap-5 p-6">
        <DialogHeader className="pb-1">
          <DialogTitle className="text-xl font-semibold tracking-tight">
            Prepare Delivery
          </DialogTitle>
          <DialogDescription className="text-ui leading-relaxed">
            Assign a fleet vehicle and driver to immediately dispatch{' '}
            <span className="font-semibold text-foreground">{order.orderNumber}</span> to the
            customer.
          </DialogDescription>
        </DialogHeader>

        {errorMessage && (
          <Alert variant="destructive">
            <AlertCircle className="size-4" />
            <AlertDescription>{errorMessage}</AlertDescription>
          </Alert>
        )}

        <form onSubmit={handleDispatch} className="flex flex-col gap-4">
          {/* Dispatch Overview Box */}
          <div className="rounded-lg bg-secondary p-4 text-sm flex flex-col gap-2">
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">Fulfilling Warehouse:</span>
              <span className="font-medium text-foreground">
                {warehouseNames.length ? warehouseNames.join(', ') : 'No available source'}
              </span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">Cargo Items:</span>
              <span className="font-medium text-foreground text-right max-w-[260px] truncate">
                {(order?.items || [])
                  .map((i) => `Item #${i.inventoryItemId} (x${i.quantity})`)
                  .join(', ')}
              </span>
            </div>
            <div className="flex items-center justify-between border-t border-border pt-2">
              <span className="text-muted-foreground">Total Order Value:</span>
              <span className="font-semibold tabular-nums text-foreground">
                ₱
                {(order?.items || [])
                  .reduce((sum, i) => sum + parseFloat(i?.totalAmount || '0'), 0)
                  .toLocaleString('en-US', { minimumFractionDigits: 2 })}
              </span>
            </div>
          </div>

          {/* Vehicle Assignment */}
          <div className="flex flex-col gap-1.5">
            <Label className="text-ui font-medium flex items-center gap-1.5">
              <Truck className="size-3.5 text-muted-foreground" />
              Delivery Vehicle *
            </Label>
            <Select value={selectedVehicleId} onValueChange={setSelectedVehicleId}>
              <SelectTrigger className="h-9 text-ui">
                <SelectValue placeholder="Select available vehicle unit..." />
              </SelectTrigger>
              <SelectContent>
                {availableVehicles.length === 0 ? (
                  <div className="p-2 text-xs text-muted-foreground text-center">
                    No available vehicles. Check Vehicles to see current assignments.
                  </div>
                ) : (
                  availableVehicles.map((vehicle) => (
                    <SelectItem key={vehicle.id} value={String(vehicle.id)}>
                      <span className="font-medium text-foreground">{vehicle.plateNumber}</span> -{' '}
                      {vehicle.model || vehicle.vehicleType}{' '}
                      <span className="text-xs text-status-success-foreground font-medium">
                        (Available)
                      </span>
                    </SelectItem>
                  ))
                )}
              </SelectContent>
            </Select>
            {availableVehicles.length === 0 && (
              <p className="text-xs text-status-warning-foreground mt-1">
                All vehicles are currently in transit or maintenance.
              </p>
            )}
          </div>

          {/* Driver Assignment */}
          <div className="flex flex-col gap-1.5">
            <Label className="text-ui font-medium flex items-center gap-1.5">
              <UserRound className="size-3.5 text-muted-foreground" />
              Assigned Driver / Staff *
            </Label>
            <Select value={selectedDriverId} onValueChange={setSelectedDriverId}>
              <SelectTrigger className="h-9 text-ui">
                <SelectValue placeholder="Select delivery driver / staff..." />
              </SelectTrigger>
              <SelectContent>
                {activeEmployees.length === 0 ? (
                  <div className="p-2 text-xs text-muted-foreground text-center">
                    No active staff found.
                  </div>
                ) : (
                  activeEmployees.map((emp) => (
                    <SelectItem key={emp.id} value={String(emp.id)}>
                      {emp.firstName} {emp.lastName}{' '}
                      {emp.phone && <span className="text-muted-foreground">({emp.phone})</span>}
                    </SelectItem>
                  ))
                )}
              </SelectContent>
            </Select>
          </div>

          {/* Departure Date/Time & Destination */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div className="flex flex-col gap-1.5">
              <Label className="text-ui font-medium flex items-center gap-1.5">
                <Clock className="size-3.5 text-muted-foreground" />
                Departure Time
              </Label>
              <Input
                type="datetime-local"
                value={scheduledAt}
                onChange={(e) => setScheduledAt(e.target.value)}
                className="h-9 text-ui"
              />
            </div>

            <div className="flex flex-col gap-1.5">
              <Label className="text-ui font-medium flex items-center gap-1.5">
                <MapPin className="size-3.5 text-muted-foreground" />
                Destination Address
              </Label>
              <Input
                value={order.deliveryAddress}
                readOnly
                aria-label="Destination address from sales order"
                className="h-9 text-ui"
                placeholder="Customer store / delivery dock"
              />
            </div>
          </div>

          {/* Delivery Notes */}
          <div className="flex flex-col gap-1.5">
            <Label className="text-ui font-medium text-muted-foreground">
              Dispatch Instructions / Gate Pass (Optional)
            </Label>
            <Input
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              className="h-9 text-ui"
              placeholder="e.g. Call customer before arrival, fragile produce..."
            />
          </div>

          <DialogFooter className="pt-2 gap-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onClose}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              size="sm"
              disabled={isSubmitting || availableVehicles.length === 0}
              className="font-medium"
            >
              {isSubmitting ? (
                'Dispatching...'
              ) : (
                <span className="flex items-center gap-1.5">
                  <PackageCheck className="size-4" />
                  Confirm & Dispatch Truck
                </span>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

