import { useId, useMemo, useRef, useState, type ReactNode } from 'react'
import { Check, Search } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Input } from '@/components/ui/input'
import { OverflowValue } from '@/components/ui/OverflowValue'
import { cn } from '@/lib/utils'

type SearchableDropdownProps<T> = {
  id?: string
  onCreateValue?: (value: string) => void
  maxCustomLength?: number
  options: T[]
  value: string
  onValueChange: (value: string, option: T) => void
  getOptionValue: (option: T) => string
  getOptionLabel: (option: T) => string
  getOptionSearchText?: (option: T) => string
  renderOption?: (option: T) => ReactNode
  placeholder: string
  searchPlaceholder: string
  emptyMessage: string
  ariaLabel: string
  className?: string
  contentClassName?: string
  align?: 'start' | 'center' | 'end'
  side?: 'top' | 'right' | 'bottom' | 'left'
  avoidCollisions?: boolean
}

export function SearchableDropdown<T>({
  id,
  onCreateValue,
  maxCustomLength = 100,
  options,
  value,
  onValueChange,
  getOptionValue,
  getOptionLabel,
  getOptionSearchText = getOptionLabel,
  renderOption,
  placeholder,
  searchPlaceholder,
  emptyMessage,
  ariaLabel,
  className,
  contentClassName,
  align = 'start',
  side = 'bottom',
  avoidCollisions,
}: SearchableDropdownProps<T>) {
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const searchInputRef = useRef<HTMLInputElement>(null)

  const validationId = useId()
  const customValue = query.trim().replace(/\s+/g, ' ')
  const exactMatch = options.find(
    (option) =>
      getOptionLabel(option).trim().replace(/\s+/g, ' ').toLocaleLowerCase() ===
      customValue.toLocaleLowerCase(),
