import { act, fireEvent, render, renderHook, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { OrdersView } from '@/components/orders/OrdersView'
import { OrderModal } from '@/components/orders/OrderModal'
import { apiClient } from '@/lib/api-client'
import { useSalesOrderEntry } from './sales-order-entry.hooks'
import * as salesApi from './sales-orders.api'
import type { SalesOrderRecord } from './sales-orders.types'

const timestamps = { createdAt: '2026-10-01', updatedAt: '2026-10-01' }
const clients = [
  {
    id: 7,
    name: 'Customer',
    address: 'Customer address',
    isActive: true,
    contactPerson: null,
    phone: null,
    email: null,
    ...timestamps,
  },
]
const products = [1, 2].map((id) => ({
  id,
  name: `Product ${id}`,
  variety: null,
  description: null,
  unit: 'kg',
  unitPrice: '100.00',
  isActive: true,
  ...timestamps,
}))
const draft: SalesOrderRecord = {
  id: 42,
  revision: 3,
  orderNumber: 'SO-42',
  status: 'DRAFT',
  clientId: 7,
  deliveryAddress: 'Original address',
  orderedAt: '2026-10-01',
  expectedAt: '2026-11-01T15:00:00.000Z',
  confirmedAt: null,
  completedAt: null,
  cancelledAt: null,
  externalReference: 'REF',
  notes: 'Original note',
  ...timestamps,
  items: [1, 2].map((id) => ({
    id: id + 10,
    salesOrderId: 42,
    lineNumber: id,
    inventoryItemId: id,
    quantity: '2.00',
    unitPrice: '100.00',
    discountRate: '5.00',
    discountAmount: '10.00',
    taxRate: '12.00',
    taxAmount: '22.80',
    subtotalAmount: '200.00',
    taxableAmount: '190.00',
    totalAmount: '212.80',
    notes: `Line ${id}`,
    ...timestamps,
  })),
}
const submitEvent = (confirm = false) =>
  ({
    preventDefault() {},
    nativeEvent: {
      submitter: { getAttribute: () => (confirm ? 'confirm' : 'draft') },
    },
  }) as unknown as React.FormEvent<HTMLFormElement>
function setup(overrides = {}) {
  const onUpdateDraft = vi.fn().mockResolvedValue({ ...draft, revision: 4 })
  const onSubmit = vi.fn()
  const onClose = vi.fn()
  const props = {
    clients,
    products,
    cashier: 'Manager',
    draftOrder: draft,
    onUpdateDraft,
    onSubmit,
    onClose,
    ...overrides,
  }
  return { ...renderHook(() => useSalesOrderEntry(props)), onUpdateDraft, onSubmit, onClose }
}
const originalAdapter = apiClient.defaults.adapter
afterEach(() => {
  apiClient.defaults.adapter = originalAdapter
})
let role: 'ADMIN' | 'MANAGER' | 'STAFF' = 'ADMIN'
beforeEach(() => {
  role = 'ADMIN'
})
vi.mock('@/features/auth/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 1, fullName: 'Test User' },
    isAdmin: role === 'ADMIN',
    isManager: role === 'MANAGER',
  }),
}))

