import { fireEvent, render, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { OrderModal } from '@/components/orders/OrderModal'
import { PurchaseModal } from '@/components/purchases/PurchaseModal'
import { buildSalesOrderPayload } from './crm/sales-order-entry.utils'
import { createSalesOrderApi, updateSalesOrderDraftApi } from './crm/sales-orders.api'
import { createPurchaseOrderApi, updatePurchaseOrderDraftApi } from './logistics/purchase-orders.api'
import { apiClient } from '@/lib/api-client'
import type { PurchaseOrderRecord } from './logistics/purchase-orders.types'
import { orderLineAmounts, orderLineTotals, savedLineDiscount, discountFields } from '@/lib/order-line-pricing'

const stamps = { createdAt: '2026-10-01', updatedAt: '2026-10-01' }
const products = [{ id: 1, name: 'Test Mango', variety: null, unit: 'kg', description: null,
  unitPrice: '100.00', isActive: true, ...stamps }]
const clients = [{ id: 1, name: 'Customer', address: 'Davao', contactPerson: null,
  phone: null, email: null, isActive: true, ...stamps }]
const suppliers = [{ id: 1, code: 'SUP-1', name: 'Supplier', address: 'Davao',
  contactPerson: null, phone: null, email: null, isActive: true, ...stamps }]
const originalAdapter = apiClient.defaults.adapter
afterEach(() => { apiClient.defaults.adapter = originalAdapter })

describe('precise backend line arithmetic', () => {
  const base = { quantity: '2.00', unitPrice: '100.00', taxRate: '12.00' }
  it.each([
    { name: 'no discount', fields: {}, discount: '0.00', vat: '24.00', total: '224.00' },
    { name: 'percentage', fields: { discountRate: '10.00' }, discount: '20.00', vat: '21.60', total: '201.60' },
    { name: 'fixed once for the whole line', fields: { discountAmount: '10.00' }, discount: '10.00', vat: '22.80', total: '212.80' },
    { name: 'explicit fixed zero', fields: { discountAmount: '0.00' }, discount: '0.00', vat: '24.00', total: '224.00' },
    { name: 'full subtotal', fields: { discountAmount: '200.00' }, discount: '200.00', vat: '0.00', total: '0.00' },
    { name: '100 percent', fields: { discountRate: '100.00' }, discount: '200.00', vat: '0.00', total: '0.00' },
  ])('$name follows subtotal → discount → tax', ({ fields, discount, vat, total }) => {
    expect(orderLineAmounts({ ...base, ...fields })).toEqual({ subtotal: '200.00', discount, vat, total })
  })
  it.each([
    { discountAmount: '-0.01' }, { discountAmount: '0.001' }, { discountAmount: '200.01' },
    { discountRate: '100.01' }, { discountRate: '-1' }, { discountRate: '1.001' },
    { discountRate: '0.00', discountAmount: '0.00' },
  ])('rejects invalid discount fields %j', (fields) => {
    expect(orderLineAmounts({ ...base, ...fields })).toBeNull()
  })
  it('compares fixed discounts against the rounded subtotal and sums rounded lines', () => {
    expect(orderLineAmounts({ quantity: '0.50', unitPrice: '0.05', discountAmount: '0.03', taxRate: '5.00' }))
      .toEqual({ subtotal: '0.03', discount: '0.03', vat: '0.00', total: '0.00' })
    expect(orderLineAmounts({ quantity: '1', unitPrice: '9999999999.99', discountAmount: '0.01' })?.total).toBe('9999999999.98')
    expect(orderLineTotals([1, 2].map(() => ({ quantity: '0.01', unitPrice: '0.50', discountRate: '50', taxRate: '5.00' }))))
      .toEqual({ subtotal: '0.02', discount: '0.02', vat: '0.00', total: '0.00' })
    expect(orderLineAmounts({ ...base, discountAmount: '10.01', taxRate: '5.00' })?.total).toBe('199.49')
  })
  it('distinguishes saved fixed amounts from calculated percentage response amounts', () => {
    expect(discountFields(savedLineDiscount({ discountRate: '0.00', discountAmount: '10.01' }))).toEqual({ discountAmount: '10.01' })
    expect(discountFields(savedLineDiscount({ discountRate: '5.00', discountAmount: '10.00' }))).toEqual({ discountRate: '5.00' })
  })
})

describe('discount request contracts', () => {
  const endpoints = [
    { name: 'sales create', path: '/sales-orders', send: (item: object) => createSalesOrderApi({ clientId: 1, deliveryAddress: 'Davao', items: [item] } as Parameters<typeof createSalesOrderApi>[0]) },
    { name: 'purchase create', path: '/purchase-orders', send: (item: object) => createPurchaseOrderApi({ items: [item] } as Parameters<typeof createPurchaseOrderApi>[0]) },
    { name: 'purchase draft', path: '/purchase-orders/7/draft', send: (item: object) => updatePurchaseOrderDraftApi(7, { items: [item] } as Parameters<typeof updatePurchaseOrderDraftApi>[1]) },
  ]
  const baseLine = { inventoryItemId: 1, quantity: '2.00', unitPrice: '100.00', taxRate: '12.00' }
  it.each(endpoints)('sends exact fixed pesos and preserves authoritative response totals for $name', async ({ path, send }) => {
    const server = { id: 7, items: [{ ...baseLine, discountRate: '0.00', discountAmount: '10.01', totalAmount: '212.79' }] }
    apiClient.defaults.adapter = async (config) => {
      expect(config.url).toBe(path)
      expect(JSON.parse(config.data).items).toEqual([{ ...baseLine, discountAmount: '10.01' }])
      return { config, status: 200, statusText: 'OK', headers: {}, data: server }
    }
    await expect(send({ ...baseLine, discountAmount: '10.01' })).resolves.toEqual(server)
  })
  it.each(endpoints)('rejects simultaneous discount fields, including zero, before sending $name', async ({ send }) => {
    const adapter = vi.fn()
    apiClient.defaults.adapter = adapter
    await expect(send({ ...baseLine, discountAmount: '0.00', discountRate: '0.00' })).rejects.toThrow(/either|both/i)
    expect(adapter).not.toHaveBeenCalled()
  })
  it('does not send fixed discounts to the unverified Sales Order draft item DTO', async () => {
    const adapter = vi.fn()
    apiClient.defaults.adapter = adapter
    await expect(updateSalesOrderDraftApi(7, { expectedRevision: 1,
      items: [{ ...baseLine, discountAmount: '10.00' }] })).rejects.toThrow(/fixed.*draft/i)
    expect(adapter).not.toHaveBeenCalled()
  })
})

